_PURE__*/_jsx("p",{className:"text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1",children:"Last Updated: July 12, 2026"})]}),/*#__PURE__*/_jsx("p",{children:"Chilton App Works, LLC (\"86 Chaos,\" \"we,\" \"us,\" or \"our\") operates the 86 Chaos restaurant operations web app, progressive web app, application programming interfaces, and related services (the \"Service\"). This policy explains what information the Service processes, why it is used, how long it is kept, and how privacy requests are handled."}),/*#__PURE__*/_jsx("p",{children:"86 Chaos is a business-to-business workplace tool. The restaurant or other organization that creates a workspace generally decides what employee and operational information is entered and how the Service is used. In that setting, the restaurant is normally the business or data controller and 86 Chaos acts as its service provider or data processor. This policy does not replace an employer's own employee privacy notice, payroll obligations, recordkeeping duties, or consent requirements."}),/*#__PURE__*/_jsx("h4",{className:"font-black text-[#D4A381] text-sm mt-4",children:"1. Information We Process"}),/*#__PURE__*/_jsx("p",{children:"Depending on the features your restaurant enables, the Service may process:"}),/*#__PURE__*/_jsxs("ul",{className:"list-disc pl-5 space-y-1 mt-1 text-slate-400",children:[/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Account and Staff Information:"})," name, email or login label, phone number, profile photo, job role, permissions, workspace identifiers, account status, and security settings."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Scheduling, Payroll-Support, and Labor Information:"})," shifts, time punches, time-off and trade requests, wage labels entered by management, tips, approvals, punch corrections, and manager notes. 86 Chaos is not the employer or payroll processor of record unless a separate written agreement says otherwise."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Location Information:"})," precise GPS coordinates may be requested when a restaurant enables location-based punch verification. The location is compared with the restaurant's configured work area. 86 Chaos does not intentionally run continuous background location tracking."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Restaurant Operations Content:"})," prep lists, 86 alerts, inventory, recipes, invoices, vendor details, menu data, maintenance records, sales or ledger entries, messages, reminders, attachments, and administrative records."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Camera, Files, and Photos:"})," files submitted for menu or invoice scanning, profile photos, message attachments, maintenance photos, logos, and similar workflows."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Device, Security, and Diagnostic Data:"})," browser or device type, screen size, active app section, notification status, push-token status, service-worker and IndexedDB support, audit events, error reports, MFA status, App Check results, and recent app actions associated with troubleshooting."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Plan, Subscription, and Billing-Support Data:"})," workspace plan, Founder Beta status and dates, selected future tier, discount status, manual billing notes, scan-limit usage, integration lock status, and plan-change audit records. Live payment processing is not active unless a separate billing provider is enabled later."]})]}),/*#__PURE__*/_jsx("h4",{className:"font-black text-[#D4A381] text-sm mt-4",children:"2. How We Use Information"}),/*#__PURE__*/_jsxs("ul",{className:"list-disc pl-5 space-y-1 mt-1 text-slate-400",children:[/*#__PURE__*/_jsx("li",{children:"Provide scheduling, time clock, staff, inventory, prep, menu, maintenance, messaging, reminders, financial/labor, backup, plan access, scan-limit, and support functions."}),/*#__PURE__*/_jsx("li",{children:"Verify location-based punches when enabled and flag exceptions for authorized managers."}),/*#__PURE__*/_jsx("li",{children:"Deliver schedule, message, reminder, security, and operational notifications."}),/*#__PURE__*/_jsx("li",{children:"Secure accounts, enforce permissions, investigate abuse, diagnose failures, maintain audit trails, and restore data."}),/*#__PURE__*/_jsx("li",{children:"Comply with law, enforce agreements, protect users and the Service, and establish or defend legal claims."})]}),/*#__PURE__*/_jsx("h4",{className:"font-black text-[#D4A381] text-sm mt-4",children:"3. AI-Assisted Features"}),/*#__PURE__*/_jsx("p",{children:"Menu and invoice scans may be sent to an AI provider for extraction or classification. The Gemini Administrator Manual may receive a Super Admin's question, matched help articles, and redacted system context. OpenAI diagnostics may receive redacted health information for structured repair guidance. The Service is designed to remove credentials, tokens, signed URLs, and similar secrets before diagnostics are sent, but administrators must not intentionally paste private keys, passwords, full employee files, or other unnecessary personal information into AI prompts."}),/*#__PURE__*/_jsx("p",{children:"AI output may be incomplete or incorrect and must be reviewed by an authorized person. 86 Chaos does not use AI output by itself to make hiring, firing, discipline, wage, scheduling, or other legally significant employment decisions."}),/*#__PURE__*/_jsx("h4",{className:"font-black text-[#D4A381] text-sm mt-4",children:"4. Sharing and Service Providers"}),/*#__PURE__*/_jsx("p",{children:"We do not sell personal information, and we do not share personal information for cross-context behavioral advertising. Information may be disclosed only as reasonably necessary to operate the Service, follow workspace instructions, comply with law, complete a business transaction, or protect rights and safety."}),/*#__PURE__*/_jsxs("ul",{className:"list-disc pl-5 space-y-1 mt-1 text-slate-400",children:[/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Google Cloud and Firebase:"})," authentication, database, Cloud Storage, push notifications, App Check, scheduled functions, logs, and related infrastructure."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Vercel:"})," web hosting, deployments, and serverless API routes."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"AI providers:"})," limited content required for an enabled scan, administrator-manual, or diagnostics workflow."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Customer-selected integrations:"})," payroll, accounting, POS, notification, or other providers if those integrations are enabled in the future and connected by the restaurant. Current customer integration setup is locked while rollout testing continues."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Legal and safety disclosures:"})," government authorities, courts, advisers, insurers, or affected parties when reasonably necessary and legally permitted."]})]}),/*#__PURE__*/_jsx("h4",{className:"font-black text-[#D4A381] text-sm mt-4",children:"5. Restaurant and Employer Responsibilities"}),/*#__PURE__*/_jsx("p",{children:"Restaurants control most workspace records and determine who may access them. Restaurants are responsible for giving legally required employee notices, obtaining any required consent for location or monitoring features, configuring permissions, reviewing AI output, responding to employment-record requests, and selecting retention periods that satisfy their own legal obligations. Employees should normally contact their restaurant first to access or correct workplace records."}),/*#__PURE__*/_jsx("h4",{className:"font-black text-[#D4A381] text-sm mt-4",children:"6. Data Retention and Deletion"}),/*#__PURE__*/_jsxs("ul",{className:"list-disc pl-5 space-y-1 mt-1 text-slate-400",children:[/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Prep lists and 86 alerts:"})," scheduled for permanent deletion after 30 days."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Raw AI upload files:"})," menu and invoice image files under the AI-upload storage paths are scheduled for deletion after 30 days. Parsed or manager-approved business records may remain separately in Firestore."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Time punches and location logs:"})," removed from active Firestore after 365 days, written to a restricted archive, and retained until the three-year mark measured from the record date."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Database backups:"})," kept on a 30-day rolling basis."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Audit and security logs:"})," retained for 1 year unless a legal hold, security investigation, dispute, or required recordkeeping obligation applies."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Deleted workspaces:"})," disabled when marked deleted and permanently removed after a 30-day recovery period unless restored."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Plan, billing-support, and subscription records:"})," kept as needed for account administration, Founder Beta discounts, audit logs, fraud prevention, support, disputes, tax/accounting needs if billing later activates, and legal obligations."]}),/*#__PURE__*/_jsxs("li",{children:[/*#__PURE__*/_jsx("strong",{className:"text-white",children:"Other records:"})," kept only as long as reasonably needed for the Service, customer instructions, security, billing, dispute resolution, backups, fraud prevention, or legal obligations."]})]}),/*#__PURE__*/_jsx("p",{children:"Scheduled deletion normally occurs during the next cleanup run and may take up to approximately 24 hours after a stated deadline. Provider-level backups, disaster-recovery copies, or soft-deleted objects may remain inaccessible for a limited additional period before automatic expiration. Legal holds, active investigations, disputes, and mandatory recordkeeping obligations may pause deletion. When a hold ends, the applicable retention schedule resumes."}),/*#__PURE__*/_jsx("h4",{className:"font-black text-[#D4A381] text-sm mt-4",children:"7. Privacy Rights and Requests"}),/*#__PURE__*/_jsx("p",{children:"Depending on where you live, you may have the right to request access, correction, deletion, restriction, objection, or a portable copy of personal information. You may also have the right to appeal a denied request. Because workplace information is usually controlled by the restaurant, we may forward a request to the appropriate workspace administrator. We may verify identity and authority before acting, and an authorized agent may be required to provide proof of authority."}),/*#__PURE__*/_jsx("p",{children:"Some information cannot be deleted immediately when retention is required for payroll, tax, safety, fraud prevention, legal claims, or another lawful purpose. We will not discriminate against a person for making a legally protected privacy request."}),/*#__PURE__*/_jsx("h4",{className:"font-black text-[#D4A381] text-sm mt-4",children:"8. Location, Notifications, and Device Permissions"}),/*#__PURE__*/_jsx("p",{children:"Browser permissions for location, camera, files, and notifications can be denied or revoked through device settings, but related features may stop working. Location is requested only for enabled punch-verification workflows. Push-notification tokens identify an app installation for delivery and are not used for advertising."}),/*#__PURE__*/_jsx("h4",{className:"font-black text-[#D4A381] text-sm mt-4",children:"9. Security and Incident Response"}),/*#__PURE__*/_jsx("p",{children:"We use authentication, role-based access, server-side authorization, Firebase security rules, optional MFA, App Check, audit logs, encryption provided by hosting vendors, diagnostics redaction, backups, and administrative controls. No security system is guaranteed. Restaurants must use strong credentials, limit elevated access, remove former workers promptly, and report suspected unauthorized access. We will investigate confirmed security incidents and provide notices when required by applicable law."}),/*#__PURE__*/_jsx("h4",{className:"font-black text-[#D4A381] text-sm mt-4",children:"10. United States Processing and Business Transfers"}),/*#__PURE__*/_jsx("p",{children:"86 Chaos is operated from the United States, and information may be processed in the United States or other locations where our service providers operate. If ownership of the Service changes through a merger, financing, reorganization, or sale, information may transfer as part of that transaction subject to applicable law and continued protection under an applicable privacy notice."}),/*#__PURE__*/_jsx("h4",{className:"font-black text-[#D4A381] text-sm mt-4",children:"11. Children"}),/*#__PURE__*/_jsx("p",{children:"The Service is not directed to children under 13, and we do not knowingly collect personal information directly from children under 13. Restaurants must not create accounts for anyone who is not legally authorized to use their workplace systems. Contact us if you believe a child's information was submitted improperly."}),/*#__PURE__*/_jsx("h4",{className:"font-black text-[#D4A381] text-sm mt-4",children:"12. Policy Changes"}),/*#__PURE__*/_jsx("p",{children:"We may update this policy as the Service, providers, or legal requirements change. The updated date will be shown above. Material changes may also be announced in the app or through the workspace administrator. Continued use after the effective date is subject to the updated policy, except where additional notice or consent is legally required."}),/*#__PURE__*/_jsx("h4",{className:"font-black text-[#D4A381] text-sm mt-4",children:"13. Contact and Privacy Requests"}),/*#__PURE__*/_jsx("p",{children:"Questions, privacy requests, suspected security incidents, and requests to appeal a privacy decision may be sent to:"}),/*#__PURE__*/_jsxs("p",{className:"text-white font-bold mt-1",children:["Email: support@86chaos.com",/*#__PURE__*/_jsx("br",{}),"Company: Chilton App Works, LLC",/*#__PURE__*/_jsx("br",{}),"Product: 86 Chaos"]}),"        "]})})]});};export{LoginScreen};

